rep("const N=A.length/4;","""// Spiral galaxy dust arms (rigid, so the loop stays seamless)
for(let j=0;j<40000;j++){
  const arm=j%3, r=3.2+Math.pow(rnd(),0.8)*15.5, a=arm*2.0944+r*0.42+(rnd()-.5)*(0.25+r*0.02);
  tmp.copy(PAL[[4,1,0][arm]]).lerp(PAL[rnd()<.5?0:5],rnd()*0.5);
  add(r,a,1,0.0, (rnd()-.5)*.25,(rnd()-.5)*.35*(1+r*.05),(rnd()-.5)*.25, 0,0.7, tmp,0.38);
}
// Comets with long tails
for(let i=0;i<14;i++){
  const oR=5+rnd()*13, k=(rnd()<.5?-1:1)*(2+Math.floor(rnd()*3)), tilt=(rnd()-.5)*2.2, a0=rnd()*6.283;
  const col=PAL[Math.floor(rnd()*PAL.length)];
  for(let j=0;j<1800;j++){
    const u=Math.pow(rnd(),2.2), off=-u*(k>0?1:-1)*1.1;
    tmp.copy(col).lerp(new THREE.Color(1,1,1),(1-u)*0.6);
    add(oR,a0+off,k,tilt, (rnd()-.5)*.06*(1+u*4),(rnd()-.5)*.06*(1+u*4),(rnd()-.5)*.06*(1+u*4), 0,0.6+(1-u)*1.4, tmp,0.35+(1-u)*1.0);
  }
}
const N=A.length/4;""")
rep("uPx:{value:innerHeight*renderer.getPixelRatio()*0.5}","uPx:{value:innerHeight*renderer.getPixelRatio()*0.5}, uW:{value:new THREE.Vector2(0,0)}")
rep("uniform float uT,uMS,uPx; uniform vec3 uM;","uniform float uT,uMS,uPx; uniform vec3 uM; uniform vec2 uW;")
rep("vec3 rotX(vec3 p,float a)","""vec3 hue(vec3 v,float a){vec3 k=vec3(0.57735);float c=cos(a),s=sin(a);return max(v*c+cross(k,v)*s+k*dot(k,v)*(1.-c),0.);}
    vec3 rotX(vec3 p,float a)""")
rep("      vec4 mv=modelViewMatrix","""      float wv=exp(-pow((dd-uW.x)*0.9,2.))*uW.y;            // click shockwave
      p+=normalize(d+1e-4)*wv*2.5; p.y+=wv*sin(dd*2.)*0.8;

      vec4 mv=modelViewMatrix""")
rep("float sz=aS.y*(1.+1.6*ce+f*1.5+b*1.2)*tw;","float sz=aS.y*(1.+1.6*ce+f*1.5+b*1.2+wv*2.)*tw;")
rep("vec3 col=aC*(1.+1.2*ce+f*1.3+b*0.9);","vec3 col=hue(aC,1.3*sin(TAU*t)+len*0.07)*(1.+1.2*ce+f*1.3+b*0.9+wv*1.5);")
rep("""composer.addPass(bloom);
composer.addPass(new OutputPass());""","""const after=new AfterimagePass(0.88);
composer.addPass(after);
composer.addPass(bloom);
const fx=new ShaderPass({
  uniforms:{tDiffuse:{value:null},uA:{value:0.002},uT:{value:0}},
  vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',
  fragmentShader:`uniform sampler2D tDiffuse;uniform float uA,uT;varying vec2 vUv;
  void main(){vec2 c=vUv-.5;float r=dot(c,c);vec2 o=c*(uA*(1.+r*6.));
    vec3 col=vec3(texture2D(tDiffuse,vUv+o).r,texture2D(tDiffuse,vUv).g,texture2D(tDiffuse,vUv-o).b);
    col*=1.-smoothstep(.25,.75,r*1.8)*.85; gl_FragColor=vec4(col,1.);}`
});
composer.addPass(fx);
composer.addPass(new OutputPass());

// shockwave rings fired at the burst
const rings=[0,1].map(()=>new THREE.Mesh(new THREE.RingGeometry(0.97,1,128),
  new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:0,side:THREE.DoubleSide,blending:THREE.AdditiveBlending,depthWrite:false})));
rings.forEach((r,i)=>{r.rotation.x=-Math.PI/2+i*0.5;r.rotation.y=i*0.4;scene.add(r)});
let waveT=99;""")
rep("addEventListener('pointerdown',e=>{pressed=true;","addEventListener('pointerdown',e=>{pressed=true;waveT=0;")
rep("  bloom.strength=","""  waveT+=1/60; uniforms.uW.value.set(waveT*16,Math.max(0,1-waveT/1.3));
  rings.forEach((r,i)=>{
    const u=(t-0.5-i*0.04)/0.4, on=u>0&&u<1;
    r.visible=on; if(on){r.scale.setScalar(0.5+u*34);r.material.opacity=Math.pow(1-u,2)*0.9;
      r.material.color.setHSL((0.5+i*0.3+u*0.3)%1,1,0.6);}
  });
  fx.uniforms.uA.value=0.0015+0.012*Math.pow(Math.sin(Math.PI*t),10)+0.01*uniforms.uW.value.y;
  bloom.strength=""")
open(f,'w').write(s)
EOF
